Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        int n = Reader.nextInt();
        String s = Reader.next().replaceAll("_+", " ");

        String processed = s.chars()
            .mapToObj(c -> (char)c)
            .map(ch -> ch == '(' ? " ( " : ch == ')' ? " ) " : ch.toString())
            .collect(Collectors.joining());

        String[] parts = processed.split(" +");

        boolean inside = false;
        int maxLen = 0, cnt = 0;

        for (String part : parts) {
            if (part.contains("(")) {
                inside = true;
            } else if (part.contains(")")) {
                inside = false;
            } else if (!part.contains("(") && !part.contains(")")) {
                if (inside) {
                    cnt++;
                } else {
                    maxLen = Math.max(maxLen, part.length());
                }
            }
        }

        System.out.println(maxLen + " " + cnt);
    }
}

class Reader {
    static BufferedReader reader;
    static StringTokenizer tokenizer;

    public static int parse(String x) {
        int num = 0;
        int i = 0;
        boolean neg = false;
        if (x.charAt(0) == '-') {
            neg = true;
            i = 1;
        }
        for (; i < x.length(); i++) {
            num = num * 10 + (x.charAt(i) - '0');
        }
        return neg ? -num : num;
    }

    static void init(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = new StringTokenizer("");
    }

    static void init(FileReader input) {
        reader = new BufferedReader(input);
        tokenizer = new StringTokenizer("");
    }

    static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    static int nextInt() throws IOException {
        return parse(next());
    }

    static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}
